#!/usr/bin/env bash
# Documentation : « Tester de bout en bout » (Qualité, chapitre 4) ; configuration à jour.
# Prérequis : apply-e2e.sh et apply-docs-droits-image.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-e2e.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx" 2>/dev/null | grep -qF "Un test doit pouvoir échouer"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "AKFC_E2E" "apps/web/next.config.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-e2e.sh"; exit 1; }
grep -qF "les droits ne changent que si des droits plus récents sont enregistrés" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-droits-image.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/configuration/next-config.mdx" "apps/web/content/docs/dev/configuration/package-json-et-monorepo.mdx" "apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx" "apps/web/content/docs/dev/qualite/la-chaine-pnpm-check.mdx" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx")
EXPECT=("5fde8a00a828:apps/web/content/docs/dev/configuration/next-config.mdx" "79d283ceac4f:apps/web/content/docs/dev/configuration/package-json-et-monorepo.mdx" "44c5da6ee11e:apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx" "f805fdac623c:apps/web/content/docs/dev/qualite/la-chaine-pnpm-check.mdx" "691cded7cac9:apps/web/content/docs/dev/qualite/les-gardes-maison.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Un test doit pouvoir échouer" "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/qualite"
base64 -d > "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx" <<'B64'
